#include<unistd.h>
#include<stdio.h>
#include<iostream>
#include<fcntl.h>
#include<sys/wait.h>
#include<sys/stat.h>
usingnamespacestd;
intmain(){
pid_treturnedValue=fork();
if(returnedValue<0){
perror("errorforking");
return-1;
}elseif(returnedValue==0){
if(close(STDOUT_FILENO)<0){
perror("errorclosingstandardoutput");
return-1;
}
//Whenthereisnoerror,openreturnsthesmallestfile
//descriptornotalreadyinusebythisprocess,sohaving
//closedSTDOUT_FILENO,theopenshouldreusethatnumber.
if(open("my-processes",O_WRONLY|O_CREAT|O_TRUNC,
S_IRUSR|S_IWUSR)<0){
perror("erroropeningmy-processes");
return-1;
}
execlp("ps","ps","l",NULL);//pswithoptionletterl
perror("errorexecutingps");
return-1;
}else{
if(waitpid(returnedValue,0,0)<0){
perror("errorwaitingforchild");
return-1;
}
cout<<"Notetheparentstillhastheoldstandardoutput."
<<endl;
}
}
